import {showGithub,githubEvidencePanel,unlinkGithubEvidence} from './github-ui.js';
import {developmentPanel,mountDevelopment} from './development.js';
import {showJira} from './jira-ui.js';
import {seed,findings,apply,generate,importRpm} from './domain.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('traceworks.v1'));if(!state?.rpms||!state?.epics||!state?.systems||!state?.history)state=null;}catch{}state ||=seed();let view='Overview',selected=null,filter='';
const pill=(s,w=false)=>`<span class="pill ${w?'warn':''}">${esc(s)}</span>`;
function notify(t){$('#notice').textContent=t;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').textContent='',5000);}
function save(){try{localStorage.setItem('traceworks.v1',JSON.stringify(state));}catch{notify('Browser storage is unavailable. Changes last for this session only.');}}
function go(v,id=null){view=v;selected=id;filter='';render();}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${action}</div></div>`;}
function requirementTable(){let rows=state.rpms.filter(r=>(r.id+' '+r.title).toLowerCase().includes(filter.toLowerCase()));return `<div class="table-wrap"><table><thead><tr><th>Government RPM</th><th>Requirement</th><th>Initiative</th><th>Coverage</th></tr></thead><tbody>${rows.map(r=>`<tr><td><div class="key">${esc(r.id)}</div><button class="link" data-rpm="${esc(r.id)}">${esc(r.title)}</button></td><td>${r.req?esc(r.req):pill('Missing',true)}</td><td>${r.initiative?esc(r.initiative):pill('Missing',true)}</td><td>${pill(r.req&&r.initiative?'Linked':'Needs attention',!r.req||!r.initiative)}</td></tr>`).join('')||'<tr><td colspan="4">No RPMs match your search.</td></tr>'}</tbody></table></div>`;}
function findingRows(items){return items.map(f=>`<div class="list-row"><div><h3>${esc(f.title)}</h3><p><span class="key">${esc(f.target)}</span> · ${esc(f.detail)}</p></div><button data-fix="${esc(f.id)}">Review</button></div>`).join('')||'<div class="empty">All coverage checks pass for the current inventory.</div>';}
function overview(){const total=state.rpms.length,req=state.rpms.filter(r=>r.req).length,init=state.rpms.filter(r=>r.initiative).length,fs=findings(state),orphans=fs.filter(f=>f.type==='epic').length,diagrams=state.systems.filter(s=>s.diagram?.commit===s.commit).length;return heading('Program overview','From government requirement to delivered system.','<button data-action="import">+ Import RPM</button><button class="primary" data-view="Reconciliation">Run coverage check</button>')+`<div class="stats">${[['Requirement coverage',req,total,'RPMs have a Jira Requirement'],['Initiative coverage',init,total,'RPMs have a delivery Initiative'],['Unmapped Epics',orphans,null,'Epics need an Initiative'],['Architecture coverage',diagrams,state.systems.length,'Registered systems have diagrams']].map(([t,n,d,sub])=>`<div class="stat"><label>${t}</label><div class="number">${n}${d!==null?` <span class="muted" style="font-size:18px">/ ${d}</span>`:''}</div><small>${sub}</small><div class="bar"><span style="width:${d?n/d*100:0}%"></span></div></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>Requirement traceability</h2><p>Government RPM → Requirement → Initiative → delivery Epics</p></div><button class="link view-all" data-view="Requirements">View all RPMs →</button></div>${requirementTable()}</section><div class="split"><section class="panel"><div class="panel-head"><h2>Attention required</h2>${pill(fs.length+' findings',!!fs.length)}</div>${findingRows(fs.slice(0,3))}<div class="panel-head"><button class="link" data-view="Reconciliation">Review all findings →</button></div></section><section class="panel"><div class="panel-head"><h2>System registry</h2><button class="link" data-view="Architecture">Open →</button></div>${state.systems.map(s=>`<div class="list-row"><div><h3>${esc(s.name)}</h3><p>${esc(s.repo)}</p></div>${pill(s.diagram?'Generated':'Missing',!s.diagram)}</div>`).join('')}</section></div>`;}
function detail(){const r=state.rpms.find(r=>r.id===selected);if(!r)return '<p>RPM not found.</p>';const epics=state.epics.filter(e=>r.initiative&&e.initiative===r.initiative),system=state.systems.find(s=>s.id===r.system);return `<button class="link back" data-view="Requirements">← All requirements</button>`+heading(esc(r.title),`${esc(r.id)} · Revision ${esc(r.revision)}`)+`<section class="panel"><div class="panel-head"><h2>Delivery trace</h2>${pill(r.req&&r.initiative?'Linked':'Incomplete',!r.req||!r.initiative)}</div><div class="chain"><div class="node"><label>Government RPM</label><strong>${esc(r.id)}</strong><small>Requirement planning metric</small></div><div class="node"><label>Jira Requirement</label><strong>${esc(r.req||'Not created')}</strong><small>Captures the source requirement</small></div><div class="node"><label>Equivalent Initiative</label><strong>${esc(r.initiative||'Not created')}</strong><small>Owns delivery of the requirement</small></div></div><div class="source">${esc(r.text)}<p class="muted">Source: ${esc(r.source)}</p></div></section><div class="split"><section class="panel"><div class="panel-head"><div><h2>Delivery Epics</h2><p>Work that comprises ${esc(r.initiative||'the Initiative')}</p></div>${pill(epics.length+' Epics')}</div><div class="epics">${epics.map(e=>`<div class="epic"><div><div class="key">${esc(e.id)} · ${esc(e.kind)}</div><strong>${esc(e.title)}</strong></div>${pill(e.status,e.status==='In review')}</div>`).join('')||'<div class="empty">No Epics are mapped to this Initiative.</div>'}</div></section><section class="panel"><div class="panel-head"><h2>Associated system</h2></div>${system?`<div style="padding:24px"><h2>${esc(system.name)}</h2><p class="muted">${esc(system.repo)}</p><p style="margin:18px 0">Shared system context for development, compliance, and environment deployment.</p><button data-system="${system.id}">View architecture →</button></div>`:'<div class="empty">No system has been associated with this Initiative.</div>'}</section></div>`+developmentPanel(state,r)+githubEvidencePanel(r);}
function architecture(){return heading('System architecture','Diagrams generated from the sample inventory. Repository scanning is not connected.','<button class="primary" data-action="generate-all">Generate all diagrams</button>')+state.systems.filter(s=>!selected||s.id===selected).map(s=>`<section class="panel"><div class="panel-head"><div><h2>${esc(s.name)}</h2><p>${esc(s.repo)} · sample commit ${s.commit}</p></div><div class="actions">${pill(s.diagram?'Current':'Not generated',!s.diagram)}<button data-generate="${s.id}">${s.diagram?'Regenerate':'Generate diagram'}</button></div></div>${s.diagram?`<div class="architecture"><div class="diagram">${s.components.map((c,i)=>`${i?'<span class="arrow" aria-hidden="true">→</span>':''}<div class="component"><div class="key">${i===0?'INTERFACE':i===s.components.length-1?'DATA':'SERVICE'}</div><strong>${esc(c)}</strong></div>`).join('')}</div></div><div class="evidence">Sample evidence: ${s.evidence.map(esc).join(' · ')}<details><summary>Diagram source · Mermaid</summary><pre>${esc(s.diagram.source)}</pre><button data-download="${s.id}">Download .mmd</button></details></div>`:'<div class="empty">No architecture artifact yet. Generate a component diagram from this system’s sample manifest.</div>'}</section>`).join('')+(selected?'<button data-view="Architecture">Show all systems</button>':'');}
function render(){if(view==='GitHub'){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb').textContent=view;showGithub(state,save,notify);return;}if(view==='Jira'){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#crumb').textContent=view;showJira();return;}const fs=findings(state);$('nav').innerHTML=['Overview','Requirements','Reconciliation','Architecture','Activity','Jira','GitHub'].map((v,i)=>`<button class="${view===v?'active':''}" data-view="${v}"><span aria-hidden="true">${['▦','≡','⌁','◇','◷','↗','⌘'][i]}</span> &nbsp; ${v}${v==='Reconciliation'?` <span class="count">${fs.length}</span>`:''}</button>`).join('');$('#crumb').textContent=view;$('#content').innerHTML=view==='Overview'?overview():view==='Requirements'?(selected?detail():heading('Government requirements','Requirement planning metrics and their Jira delivery coverage.','<button class="primary" data-action="import">+ Import RPM</button>')+`<section class="panel"><div class="panel-head"><h2>${state.rpms.length} RPMs</h2><input class="filter" aria-label="Search RPMs" placeholder="Search identifier or title" value="${esc(filter)}"></div><div id="rpm-table">${requirementTable()}</div></section>`):view==='Reconciliation'?heading('Coverage reconciliation','Review proposed corrections before applying them to the local sample dataset.')+`<section class="panel"><div class="intro">Local simulation · Actions update this browser only. No Jira tickets are created externally.</div><div class="panel-head"><h2>${fs.length} open findings</h2>${pill('Checks calculated from current data')}</div>${findingRows(fs)}</section>`:view==='Architecture'?architecture():heading('Activity','Local import, reconciliation, and architecture history.')+`<section class="panel">${state.history.map(h=>`<div class="list-row"><div>${esc(h.text)}<p>${esc(new Date(h.at).toLocaleString())}</p></div></div>`).join('')||'<div class="empty">No changes yet. Import an RPM or resolve a coverage finding to begin.</div>'}</section>`;mountDevelopment(state,save,()=>render(),notify);}
function openDialog(html){$('#modal').innerHTML=html;$('#modal').showModal();}
function preview(id){const f=findings(state).find(f=>f.id===id);if(!f)return;const r=state.rpms.find(r=>r.id===f.target);openDialog(`<h2>${esc(f.title)}</h2><p>${esc(f.target)} · ${esc(f.detail)}</p><div class="intro" style="margin:18px 0">${f.type==='requirement'?'Create a sample Requirement in project REQ and link it to this RPM.':f.type==='initiative'?'Create a sample Initiative in project INIT and link it to the existing Requirement.':f.type==='epic'?'Map this Epic to the Initiative you select.':'Generate a component diagram from the sample system manifest.'}</div><form id="fix-form" data-id="${esc(id)}">${f.type==='epic'?`<label class="field">Parent Initiative<select name="initiative" required><option value="">Select an Initiative</option>${state.rpms.filter(r=>r.initiative).map(r=>`<option value="${esc(r.initiative)}">${esc(r.initiative)} · ${esc(r.title)}</option>`).join('')}</select></label>`:''}${f.type==='initiative'&&!r.req?'<p class="error">Create the Requirement first, then return to this finding.</p>':''}<small>Local prototype only. No external write will occur.</small><p class="error" id="form-error" role="alert"></p><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button class="primary" ${f.type==='initiative'&&!r.req?'disabled':''}>Apply to sample data</button></div></form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.unlinkGithub){unlinkGithubEvidence(state,b.dataset.requirement,b.dataset.unlinkGithub);save();render();notify('GitHub reference removed locally.');}if(b.dataset.view)go(b.dataset.view);if(b.dataset.rpm)go('Requirements',b.dataset.rpm);if(b.dataset.system)go('Architecture',b.dataset.system);if(b.dataset.fix)preview(b.dataset.fix);if(b.dataset.generate){generate(state,b.dataset.generate);state.history.unshift({at:new Date().toISOString(),text:'Generated sample architecture: '+b.dataset.generate});save();render();notify('Architecture diagram generated.');}if(b.dataset.download){const s=state.systems.find(s=>s.id===b.dataset.download);const url=URL.createObjectURL(new Blob([s.diagram.source],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=s.id+'.mmd';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(b.dataset.action==='close')$('#modal').close();if(b.dataset.action==='generate-all'){for(const s of state.systems)generate(state,s.id);state.history.unshift({at:new Date().toISOString(),text:'Generated architecture for all 3 sample systems'});save();render();notify('All system diagrams generated.');}if(b.dataset.action==='import')openDialog(`<h2>Import a government RPM</h2><p class="muted" style="margin-bottom:18px">Paste one requirement and preserve its source reference.</p><form id="import-form">${[['id','Government identifier','RPM-006'],['title','Requirement title',''],['source','Source document and section',''],['revision','Revision','1']].map(([name,label,value])=>`<label class="field">${label}<input name="${name}" value="${value}" required maxlength="${name==='id'?80:200}"></label>`).join('')}<label class="field">Original requirement text<textarea name="text" required maxlength="10000"></textarea></label><p class="error" id="form-error" role="alert"></p><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button class="primary">Import RPM</button></div></form>`);});
document.addEventListener('input',e=>{if(e.target.matches('.filter')&&$('#rpm-table')){filter=e.target.value;$('#rpm-table').innerHTML=requirementTable();}});
document.addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));if(e.target.id==='import-form'){const r=importRpm(state,data);save();$('#modal').close();go('Requirements',r.id);notify('RPM imported. Jira coverage gaps are ready for review.');}if(e.target.id==='fix-form'){apply(state,e.target.dataset.id,data.initiative);save();$('#modal').close();render();notify('Correction applied to sample data.');}}catch(err){$('#form-error').textContent=err.message;}});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_coverage_findings',description:'Read current RPM, Epic, and architecture coverage gaps in the local prototype.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');return {findings:findings(state)};}})).catch(()=>{});}catch{}}


